test('vatSummary returns empty array for no issued invoices', () => {
  const { vatSummary } = await import('../src/reports.js');
  const result = vatSummary([]);

  assert.deepEqual(result, []);
});

test('vatSummary excludes draft invoices', () => {
  const { vatSummary } = await import('../src/reports.js');
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const result = vatSummary([draft]);

  assert.deepEqual(result, []);
});

test('vatSummary includes issued invoices', () => {
  const { vatSummary } = await import('../src/reports.js');
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const result = vatSummary([issued]);

  assert.ok(Array.isArray(result));
  assert.ok(result.length > 0);
});

test('vatSummary includes partially_paid invoices', () => {
  const { vatSummary } = await import('../src/reports.js');
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const partial = recordPayment(issued, { amount: 5000, date: '2024-02-20' }).value;
  const result = vatSummary([partial]);

  assert.ok(result.length > 0);
});

test('vatSummary includes paid invoices', () => {
  const { vatSummary } = await import('../src/reports.js');
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);
  const paid = recordPayment(issued, { amount: totals.total, date: '2024-02-20' }).value;
  const result = vatSummary([paid]);

  assert.ok(result.length > 0);
});

test('vatSummary groups by VAT rate', () => {
  const { vatSummary } = await import('../src/reports.js');
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-16',
    lines: [{ sku: 'HOSTING', qty: 1 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2024-0001']).value;

  const result = vatSummary([issued1, issued2]);

  const rates = result.map((r) => r.rate);
  assert.ok(rates.includes(21));
  assert.ok(rates.includes(9));
});

test('vatSummary sorts by rate descending', () => {
  const { vatSummary } = await import('../src/reports.js');
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-16',
    lines: [{ sku: 'HOSTING', qty: 1 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2024-0001']).value;

  const result = vatSummary([issued1, issued2]);

  assert.equal(result[0].rate, 21);
  assert.equal(result[1].rate, 9);
});

test('vatSummary calculates base (line total minus discount)', () => {
  const { vatSummary } = await import('../src/reports.js');
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const result = vatSummary([issued]);

  const line21 = result.find((r) => r.rate === 21);
  assert.ok(line21);
  assert.ok(line21.base > 0);
});

test('vatSummary includes vat amount', () => {
  const { vatSummary } = await import('../src/reports.js');
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const result = vatSummary([issued]);

  const line21 = result.find((r) => r.rate === 21);
  assert.ok(line21);
  assert.ok(line21.vat > 0);
});

test('vatSummary accumulates across multiple lines with same rate', () => {
  const { vatSummary } = await import('../src/reports.js');
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const result = vatSummary([issued]);

  const line21 = result.find((r) => r.rate === 21);
  assert.ok(line21);
  assert.ok(line21.base > 0);
});

test('vatSummary accumulates across multiple invoices', () => {
  const { vatSummary } = await import('../src/reports.js');
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-16',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2024-0001']).value;

  const result = vatSummary([issued1, issued2]);

  const line21 = result.find((r) => r.rate === 21);
  assert.ok(line21);
  assert.ok(line21.base > 0);
  assert.ok(line21.vat > 0);
});

test('vatSummary includes 0% VAT rate', () => {
  const { vatSummary } = await import('../src/reports.js');
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'TRAINING', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const result = vatSummary([issued]);

  const line0 = result.find((r) => r.rate === 0);
  assert.ok(line0);
  assert.ok(line0.base > 0);
  assert.equal(line0.vat, 0);
});

test('vatSummary vat is calculated correctly', () => {
  const { vatSummary } = await import('../src/reports.js');
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const result = vatSummary([issued]);

  const line21 = result.find((r) => r.rate === 21);
  assert.ok(line21);
  const expectedVat = Math.round(line21.base * 0.21);
  assert.equal(line21.vat, expectedVat);
});

