test('vatSummary vat is calculated correctly', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
